#include "target_timing_bridge.cpp"
#include <cassert>
#include <iostream>
int main(){unsigned cases=0;for(auto rpm:{50U,200U,1200U}){Context c;c.tune.strategy=ecu::engine::Strategy::SemiSequential;c.decoder=ecu::engine::PhaseDecoder({60,2,8000},ecu::engine::angle_config(c.tune));assert(engine_crank_timeout(&c)==0);std::uint64_t last=0;const double period=60000000./(rpm*60.);for(unsigned n=0;n<240;++n){if(n%60>=58)continue;last=200000+std::llround(n*period);c.decoder.edge(last);}assert(c.decoder.crank_synced());const auto expected=rpm==50?150000U:rpm==200?40000U:20000U;const auto tooth=c.decoder.tooth();const auto decoded_rpm=c.decoder.rpm();const auto generation=c.core.stats().generation;for(unsigned n=0;n<100;++n)assert(engine_crank_timeout(&c)==expected);assert(c.decoder.tooth()==tooth&&c.decoder.rpm()==decoded_rpm&&c.core.stats().generation==generation&&!c.io.mask);c.decoder.tick(last+expected+1);assert(engine_crank_timeout(&c)==0);++cases;}std::cout<<"{\"getter_cases\":"<<cases<<",\"rpm\":[50,200,1200],\"timeouts_us\":[150000,40000,20000],\"unsynced_returns_zero\":true,\"repeated_reads_do_not_mutate_decoder_or_core\":true}\n";}
